public final class Orders extends AbstractCollection<Order> {
    private final List<Order> items = new ArrayList<>();

    @Override public boolean add(Order order) {
        Objects.requireNonNull(order);
        if (items.size() >= MAX_ORDERS) throw new IllegalStateException("order limit reached");
        return items.add(order);
    }
    @Override public Iterator<Order> iterator() { return List.copyOf(items).iterator(); }
    @Override public int size() { return items.size(); }
    public List<Order> snapshot() { return List.copyOf(items); }  // not a live view
}
